// Um iterador "manual", construído sem usar for...of
function criarIteradorDeContagem(limite) {
  let atual = 0;
  return {
    next() {
      if (atual < limite) {
        return { value: atual++, done: false };
      }
      return { value: undefined, done: true };
    },
  };
}

const iterador = criarIteradorDeContagem(3);
console.log(iterador.next()); // { value: 0, done: false }
console.log(iterador.next()); // { value: 1, done: false }
console.log(iterador.next()); // { value: 2, done: false }
console.log(iterador.next()); // { value: undefined, done: true }

const cores = ["vermelho", "verde", "azul"];

// O que o motor faz por baixo quando escrevemos for...of
const it = cores[Symbol.iterator]();
let resultado = it.next();
while (!resultado.done) {
  console.log(resultado.value);
  resultado = it.next();
}

// Exatamente o mesmo resultado, de forma legível
for (const cor of cores) {
  console.log(cor);
}

const mapa = new Map([["a", 1], ["b", 2]]);
for (const [chave, valor] of mapa) {
  console.log(chave, valor); // itera pares [chave, valor]
}

for (const caractere of "olá 👋") {
  console.log(caractere); // itera por ponto de código Unicode (o emoji conta como um único caractere)
}

class IntervaloNumerico {
  constructor(inicio, fim, passo = 1) {
    this.inicio = inicio;
    this.fim = fim;
    this.passo = passo;
  }

  [Symbol.iterator]() {
    let atual = this.inicio;
    const fim = this.fim;
    const passo = this.passo;

    return {
      next() {
        if (atual < fim) {
          const valor = atual;
          atual += passo;
          return { value: valor, done: false };
        }
        return { value: undefined, done: true };
      },
    };
  }
}

const intervalo = new IntervaloNumerico(0, 10, 2);

for (const numero of intervalo) {
  console.log(numero); // 0, 2, 4, 6, 8
}

console.log([...intervalo]); // [0, 2, 4, 6, 8]
const [primeiro, segundo] = intervalo;
console.log(primeiro, segundo); // 0 2

// Objeto mal desenhado: o iterador partilha o estado com o iterável
const contadorComBug = {
  atual: 0,
  limite: 3,
  [Symbol.iterator]() {
    return this; // devolve o próprio objeto como iterador
  },
  next() {
    if (this.atual < this.limite) {
      return { value: this.atual++, done: false };
    }
    return { value: undefined, done: true };
  },
};

console.log([...contadorComBug]); // [0, 1, 2]
console.log([...contadorComBug]); // [] -- o estado já foi consumido!

// Versão correta: cada chamada a Symbol.iterator cria estado novo
const contadorCorreto = {
  limite: 3,
  [Symbol.iterator]() {
    let atual = 0;
    const limite = this.limite;
    return {
      next() {
        return atual < limite
          ? { value: atual++, done: false }
          : { value: undefined, done: true };
      },
    };
  },
};

console.log([...contadorCorreto]); // [0, 1, 2]
console.log([...contadorCorreto]); // [0, 1, 2] -- funciona sempre

// Continua o exemplo da secção anterior: reutiliza a classe
// IntervaloNumerico, que implementa Symbol.iterator.
const intervalo = new IntervaloNumerico(1, 4);

console.log(Array.from(intervalo)); // [1, 2, 3]
console.log(new Set(intervalo));    // Set(3) {1, 2, 3}
console.log(Math.max(...intervalo)); // 3

const pessoa = { nome: "Inês", idade: 34 };

try {
  for (const valor of pessoa) {
    console.log(valor);
  }
} catch (erro) {
  console.log(erro instanceof TypeError, erro.message);
}

// Objetos simples não são iteráveis por omissão;
// percorremos as suas entradas através de um array intermédio
for (const [chave, valor] of Object.entries(pessoa)) {
  console.log(chave, valor);
}

