const nomes = ["Ana", "Bruno", "Carla"];
const it = nomes[Symbol.iterator]();

let resultado = it.next();
while (!resultado.done) {
  console.log(resultado.value);
  resultado = it.next();
}

function ehIteravel(valor) {
  return valor != null && typeof valor[Symbol.iterator] === "function";
}

console.log(ehIteravel([1, 2, 3])); // true
console.log(ehIteravel("texto"));   // true
console.log(ehIteravel(42));        // false
console.log(ehIteravel({}));        // false

const diasUteis = {
  nomes: ["Segunda", "Terça", "Quarta", "Quinta", "Sexta"],
  [Symbol.iterator]() {
    let indice = 0;
    const nomes = this.nomes;
    return {
      next() {
        if (indice < nomes.length) {
          return { value: nomes[indice++], done: false };
        }
        return { value: undefined, done: true };
      },
    };
  },
};

for (const dia of diasUteis) {
  console.log(dia);
}

const fibonacci = {
  [Symbol.iterator]() {
    let anterior = 0;
    let atual = 1;
    return {
      next() {
        const valor = anterior;
        [anterior, atual] = [atual, anterior + atual];
        return { value: valor, done: false }; // nunca termina por iniciativa própria
      },
    };
  },
};

let contador = 0;
for (const numero of fibonacci) {
  console.log(numero);
  contador++;
  if (contador === 8) break;
}

let soma = 0;
for (const numero of fibonacci) {
  soma += numero;
  if (soma > 20) break;
}
console.log(soma);
